/**
 * helpers.js
 *
 * Shared low-level utilities used by every other module in /code and by the
 * equivalent n8n Code nodes. Pure functions only — no I/O, no n8n APIs — so
 * this file can be unit tested with plain `node` and pasted into a Code node
 * body unchanged (just drop the `module.exports` line).
 *
 * Candle shape (normalized, provider-agnostic — see docs/DATA_PROVIDER.md):
 * {
 *   symbol: "COMI",
 *   date: "2026-08-18",     // ISO date, trading session date
 *   open: 100.20,
 *   high: 103.10,
 *   low: 99.80,
 *   close: 102.70,
 *   volume: 12500000,
 *   tradedValue: 1270000000 // optional, derived if absent
 * }
 */

/** Returns true if v is a finite, non-NaN number. */
function isNumber(v) {
  return typeof v === "number" && Number.isFinite(v);
}

/** Safe division: returns null instead of Infinity/NaN when denominator is unusable. */
function safeDivide(numerator, denominator) {
  if (!isNumber(numerator) || !isNumber(denominator) || denominator === 0) {
    return null;
  }
  const result = numerator / denominator;
  return Number.isFinite(result) ? result : null;
}

/** Rounds to `decimals` places, returns null for non-numeric input. */
function round(value, decimals = 4) {
  if (!isNumber(value)) return null;
  const factor = Math.pow(10, decimals);
  return Math.round(value * factor) / factor;
}

/** Percentage change from `from` to `to`. Returns null if from <= 0 or invalid. */
function pctChange(from, to) {
  if (!isNumber(from) || !isNumber(to) || from === 0) return null;
  return ((to - from) / from) * 100;
}

/**
 * Validates a single raw candle. Returns { valid, errors[] }.
 * Mirrors the rules in spec section 31.
 */
function validateCandle(candle) {
  const errors = [];
  if (!candle || typeof candle !== "object") {
    return { valid: false, errors: ["candle is not an object"] };
  }
  const { symbol, date, open, high, low, close, volume } = candle;

  if (!symbol || typeof symbol !== "string") errors.push("missing/invalid symbol");
  if (!date || Number.isNaN(Date.parse(date))) errors.push("missing/invalid date");
  if (!isNumber(open)) errors.push("open is not numeric");
  if (!isNumber(high)) errors.push("high is not numeric");
  if (!isNumber(low)) errors.push("low is not numeric");
  if (!isNumber(close)) errors.push("close is not numeric");
  if (!isNumber(volume)) errors.push("volume is not numeric");

  if (isNumber(open) && isNumber(high) && isNumber(low) && isNumber(close)) {
    if (high < open) errors.push("high < open");
    if (high < close) errors.push("high < close");
    if (high < low) errors.push("high < low");
    if (low > open) errors.push("low > open");
    if (low > close) errors.push("low > close");
  }
  if (isNumber(volume) && volume < 0) errors.push("negative volume");
  if (isNumber(close) && close <= 0) errors.push("close <= 0");

  return { valid: errors.length === 0, errors };
}

/**
 * Filters an array of raw candles into { valid[], invalid[] }.
 * `invalid` entries carry the original candle plus `.errors`.
 * Zero-volume candles are valid but flagged with a warning for downstream
 * consumers (suspicious, not necessarily wrong — EGX thin names do trade zero
 * volume on quiet sessions).
 */
function validateCandles(candles) {
  const valid = [];
  const invalid = [];
  for (const candle of candles || []) {
    const { valid: ok, errors } = validateCandle(candle);
    if (ok) {
      valid.push({ ...candle, suspiciousZeroVolume: candle.volume === 0 });
    } else {
      invalid.push({ ...candle, errors });
    }
  }
  return { valid, invalid };
}

/**
 * Removes duplicate candles (same symbol+date), keeping the last occurrence
 * (assumed most recent fetch / most authoritative).
 */
function dedupeCandles(candles) {
  const map = new Map();
  for (const c of candles || []) {
    map.set(`${c.symbol}::${c.date}`, c);
  }
  return Array.from(map.values());
}

/** Sorts candles ascending by date (oldest first) — mandatory before any TA calc. */
function sortCandlesAscending(candles) {
  return [...(candles || [])].sort((a, b) => new Date(a.date) - new Date(b.date));
}

/**
 * Derives tradedValue when the provider doesn't supply it directly.
 * Uses the session's typical price (H+L+C)/3 * volume as a reasonable proxy.
 */
function deriveTradedValue(candle) {
  if (isNumber(candle.tradedValue)) return candle.tradedValue;
  if (!isNumber(candle.high) || !isNumber(candle.low) || !isNumber(candle.close) || !isNumber(candle.volume)) {
    return null;
  }
  const typicalPrice = (candle.high + candle.low + candle.close) / 3;
  return typicalPrice * candle.volume;
}

/** Simple mean of the last `n` numeric values in `arr` (nulls skipped). Returns null if insufficient data. */
function meanOfLast(arr, n) {
  if (!Array.isArray(arr) || arr.length < n) return null;
  const slice = arr.slice(-n).filter(isNumber);
  if (slice.length < n) return null;
  return slice.reduce((a, b) => a + b, 0) / n;
}

/** Standard deviation of the last `n` numeric values. Returns null if insufficient data. */
function stdDevOfLast(arr, n) {
  const mean = meanOfLast(arr, n);
  if (mean === null) return null;
  const slice = arr.slice(-n);
  const variance = slice.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / n;
  return Math.sqrt(variance);
}

/** Clamps a number into [min, max]. */
function clamp(value, min, max) {
  if (!isNumber(value)) return min;
  return Math.min(Math.max(value, min), max);
}

/**
 * Wraps arbitrary rows into n8n's expected item structure: [{ json: {...} }].
 * Accepts a single object or array of objects.
 */
function toN8nItems(rows) {
  const list = Array.isArray(rows) ? rows : [rows];
  return list.map((json) => ({ json }));
}

/**
 * Reads all `json` payloads out of an n8n items array back into plain objects.
 */
function fromN8nItems(items) {
  return (items || []).map((item) => item.json);
}

// ---------------------------------------------------------------------

/**
 * indicators.js
 *
 * Pure technical-indicator calculations. Every function takes candles/values
 * already sorted OLDEST -> NEWEST (see helpers.sortCandlesAscending) and
 * returns an array aligned index-for-index with the input, using `null`
 * wherever there isn't enough history yet. No indicator here ever looks
 * ahead — index i only ever uses data at indices <= i (see docs/BACKTESTING.md
 * "no look-ahead" rule, spec section 30).
 */


/** Simple Moving Average over `period` closes. */
function sma(values, period) {
  const out = new Array(values.length).fill(null);
  let windowSum = 0;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    windowSum += isNumber(v) ? v : 0;
    if (i >= period) {
      const dropped = values[i - period];
      windowSum -= isNumber(dropped) ? dropped : 0;
    }
    if (i >= period - 1) {
      const slice = values.slice(i - period + 1, i + 1);
      if (slice.every(isNumber)) {
        out[i] = windowSum / period;
      }
    }
  }
  return out;
}

/** Exponential Moving Average, seeded with the SMA of the first `period` values. */
function ema(values, period) {
  const out = new Array(values.length).fill(null);
  const k = 2 / (period + 1);
  const seed = sma(values, period);
  let prevEma = null;
  for (let i = 0; i < values.length; i++) {
    if (!isNumber(values[i])) continue;
    if (prevEma === null) {
      if (seed[i] !== null) {
        prevEma = seed[i];
        out[i] = prevEma;
      }
      continue;
    }
    prevEma = values[i] * k + prevEma * (1 - k);
    out[i] = prevEma;
  }
  return out;
}

/** RSI (Wilder smoothing), period defaults to 14. */
function rsi(closes, period = 14) {
  const out = new Array(closes.length).fill(null);
  if (closes.length < period + 1) return out;

  let avgGain = 0;
  let avgLoss = 0;
  for (let i = 1; i <= period; i++) {
    const change = closes[i] - closes[i - 1];
    if (change > 0) avgGain += change;
    else avgLoss += Math.abs(change);
  }
  avgGain /= period;
  avgLoss /= period;
  out[period] = computeRsiFromAverages(avgGain, avgLoss);

  for (let i = period + 1; i < closes.length; i++) {
    const change = closes[i] - closes[i - 1];
    const gain = change > 0 ? change : 0;
    const loss = change < 0 ? Math.abs(change) : 0;
    avgGain = (avgGain * (period - 1) + gain) / period;
    avgLoss = (avgLoss * (period - 1) + loss) / period;
    out[i] = computeRsiFromAverages(avgGain, avgLoss);
  }
  return out;
}

function computeRsiFromAverages(avgGain, avgLoss) {
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return 100 - 100 / (1 + rs);
}

/** MACD: { macdLine[], signalLine[], histogram[] }. Defaults 12/26/9. */
function macd(closes, fastPeriod = 12, slowPeriod = 26, signalPeriod = 9) {
  const fastEma = ema(closes, fastPeriod);
  const slowEma = ema(closes, slowPeriod);
  const macdLine = closes.map((_, i) =>
    isNumber(fastEma[i]) && isNumber(slowEma[i]) ? fastEma[i] - slowEma[i] : null
  );
  // signal line is an EMA of the MACD line itself; emaSkippingNulls() only
  // advances its internal EMA on numeric inputs, so the leading nulls are safe.
  const signalLine = emaSkippingNulls(macdLine, signalPeriod);
  const histogram = closes.map((_, i) =>
    isNumber(macdLine[i]) && isNumber(signalLine[i]) ? macdLine[i] - signalLine[i] : null
  );
  return { macdLine, signalLine, histogram };
}

/** Like ema() but the seed window only counts from the first non-null value. */
function emaSkippingNulls(values, period) {
  const firstValidIndex = values.findIndex(isNumber);
  const out = new Array(values.length).fill(null);
  if (firstValidIndex === -1) return out;
  const compact = values.slice(firstValidIndex).filter(isNumber);
  if (compact.length < period) return out;
  const compactEma = ema(compact, period);
  let compactIdx = 0;
  for (let i = firstValidIndex; i < values.length; i++) {
    if (!isNumber(values[i])) continue;
    out[i] = compactEma[compactIdx];
    compactIdx++;
  }
  return out;
}

/** Average True Range (Wilder smoothing), period defaults to 14. */
function atr(candles, period = 14) {
  const out = new Array(candles.length).fill(null);
  if (candles.length < period + 1) return out;

  const trueRanges = candles.map((c, i) => {
    if (i === 0) return c.high - c.low;
    const prevClose = candles[i - 1].close;
    return Math.max(
      c.high - c.low,
      Math.abs(c.high - prevClose),
      Math.abs(c.low - prevClose)
    );
  });

  let avgTr = trueRanges.slice(1, period + 1).reduce((a, b) => a + b, 0) / period;
  out[period] = avgTr;
  for (let i = period + 1; i < candles.length; i++) {
    avgTr = (avgTr * (period - 1) + trueRanges[i]) / period;
    out[i] = avgTr;
  }
  return out;
}

/** On-Balance Volume, cumulative. First bar seeds at 0. */
function obv(candles) {
  const out = new Array(candles.length).fill(null);
  if (candles.length === 0) return out;
  out[0] = 0;
  for (let i = 1; i < candles.length; i++) {
    const prev = out[i - 1];
    const volume = isNumber(candles[i].volume) ? candles[i].volume : 0;
    if (candles[i].close > candles[i - 1].close) out[i] = prev + volume;
    else if (candles[i].close < candles[i - 1].close) out[i] = prev - volume;
    else out[i] = prev;
  }
  return out;
}

/** Rate of Change (%) over `period` sessions. */
function roc(closes, period) {
  return closes.map((v, i) => {
    if (i < period) return null;
    return safeDivide(v - closes[i - period], closes[i - period]) === null
      ? null
      : ((v - closes[i - period]) / closes[i - period]) * 100;
  });
}

/** Rolling max of `high` over the trailing `period` sessions, inclusive of current. */
function rollingHigh(candles, period) {
  return candles.map((_, i) => {
    if (i < period - 1) return null;
    const slice = candles.slice(i - period + 1, i + 1);
    return Math.max(...slice.map((c) => c.high));
  });
}

/** Rolling min of `low` over the trailing `period` sessions, inclusive of current. */
function rollingLow(candles, period) {
  return candles.map((_, i) => {
    if (i < period - 1) return null;
    const slice = candles.slice(i - period + 1, i + 1);
    return Math.min(...slice.map((c) => c.low));
  });
}

/** Simple moving average of volume (same mechanics as sma()). */
function averageVolume(volumes, period) {
  return sma(volumes, period);
}

/**
 * Relative volume at index i = volume[i] / average(volume[i-period .. i-1]).
 * CRITICAL: today's volume must NEVER be included in its own denominator
 * (spec section 9 / 30). The average window ends the bar BEFORE i.
 */
function relativeVolume(volumes, period) {
  return volumes.map((v, i) => {
    if (i < period) return null;
    const priorWindow = volumes.slice(i - period, i);
    if (!priorWindow.every(isNumber)) return null;
    const avg = priorWindow.reduce((a, b) => a + b, 0) / period;
    return safeDivide(v, avg);
  });
}

/**
 * Computes the full technical_analysis row set for every bar of a sorted
 * candle series. Returns an array aligned with `candles`; each element is
 * either null (insufficient history at that index for ANY indicator we still
 * want to attempt) or a flat object matching the technical_analysis table.
 *
 * This is the function the "04-egx-technical-analysis" workflow's Code node
 * mirrors. It is intentionally tolerant: partial indicator sets (e.g. no
 * SMA200 yet for a newly listed stock) still produce a row with nulls for the
 * fields that aren't computable yet, rather than skipping the bar entirely.
 */
function calculateAllIndicators(candles) {
  if (!Array.isArray(candles) || candles.length === 0) return [];

  const closes = candles.map((c) => c.close);
  const volumes = candles.map((c) => c.volume);

  const sma20 = sma(closes, 20);
  const sma50 = sma(closes, 50);
  const sma100 = sma(closes, 100);
  const sma200 = sma(closes, 200);

  const ema9 = ema(closes, 9);
  const ema20 = ema(closes, 20);
  const ema50 = ema(closes, 50);
  const ema100 = ema(closes, 100);
  const ema200 = ema(closes, 200);

  const rsi14 = rsi(closes, 14);
  const { macdLine, signalLine, histogram } = macd(closes, 12, 26, 9);
  const atr14 = atr(candles, 14);
  const obvSeries = obv(candles);

  const volumeSma20 = averageVolume(volumes, 20);
  const volumeSma50 = averageVolume(volumes, 50);
  const rvol20 = relativeVolume(volumes, 20);
  const rvol50 = relativeVolume(volumes, 50);

  const roc5 = roc(closes, 5);
  const roc10 = roc(closes, 10);
  const roc20 = roc(closes, 20);

  const high20 = rollingHigh(candles, 20);
  const high50 = rollingHigh(candles, 50);
  const high252 = rollingHigh(candles, 252);
  const low20 = rollingLow(candles, 20);
  const low50 = rollingLow(candles, 50);
  const low252 = rollingLow(candles, 252);

  return candles.map((c, i) => {
    const distance52wHigh = isNumber(high252[i]) ? ((c.close - high252[i]) / high252[i]) * 100 : null;
    const distance52wLow = isNumber(low252[i]) ? ((c.close - low252[i]) / low252[i]) * 100 : null;

    const trend = classifyTrend({
      close: c.close,
      ema9: ema9[i],
      ema20: ema20[i],
      ema50: ema50[i],
      ema200: ema200[i],
    });

    // History-length based data confidence (section 44): scales up to 100
    // once 252 sessions of prior data are available; never inflated for
    // thin history even if all indicators happen to compute.
    const barsOfHistory = i + 1;
    const dataConfidence = round(Math.min(100, (barsOfHistory / 252) * 100), 2);

    return {
      symbol: c.symbol,
      tradingDate: c.date,
      shortTermTrend: trend.shortTerm,
      mediumTermTrend: trend.mediumTerm,
      longTermTrend: trend.longTerm,
      dataConfidence,

      sma20: round(sma20[i], 6),
      sma50: round(sma50[i], 6),
      sma100: round(sma100[i], 6),
      sma200: round(sma200[i], 6),

      ema9: round(ema9[i], 6),
      ema20: round(ema20[i], 6),
      ema50: round(ema50[i], 6),
      ema100: round(ema100[i], 6),
      ema200: round(ema200[i], 6),

      rsi14: round(rsi14[i], 4),

      macd: round(macdLine[i], 6),
      macdSignal: round(signalLine[i], 6),
      macdHistogram: round(histogram[i], 6),

      atr14: round(atr14[i], 6),
      obv: obvSeries[i],

      volumeSma20: round(volumeSma20[i], 4),
      volumeSma50: round(volumeSma50[i], 4),

      relativeVolume20: round(rvol20[i], 4),
      relativeVolume50: round(rvol50[i], 4),

      roc5: round(roc5[i], 4),
      roc10: round(roc10[i], 4),
      roc20: round(roc20[i], 4),

      high20: high20[i],
      high50: high50[i],
      high252: high252[i],
      low20: low20[i],
      low50: low50[i],
      low252: low252[i],

      distance52wHigh: round(distance52wHigh, 4),
      distance52wLow: round(distance52wLow, 4),
    };
  });
}

/**
 * Classifies short/medium/long-term trend from EMA structure (spec section 11).
 * Deliberately does NOT require EMA200 for the medium-term read, since newer
 * EGX listings may not have 200 sessions of history yet — long-term trend
 * degrades to null (not BEARISH) when EMA200 is unavailable, so a thin
 * history never gets penalized as if it were structurally weak.
 *
 * close, ema9, ema20, ema50, ema200 are the latest bar's values (numbers or null).
 */
function classifyTrend({ close, ema9, ema20, ema50, ema200 }) {
  const result = { shortTerm: "NEUTRAL", mediumTerm: "NEUTRAL", longTerm: null };

  if (isNumber(close) && isNumber(ema9) && isNumber(ema20)) {
    if (close > ema9 && ema9 > ema20) result.shortTerm = "STRONG_BULLISH";
    else if (close > ema9 || close > ema20) result.shortTerm = "BULLISH";
    else if (close < ema9 && ema9 < ema20) result.shortTerm = "STRONG_BEARISH";
    else if (close < ema9 || close < ema20) result.shortTerm = "BEARISH";
  }

  if (isNumber(ema20) && isNumber(ema50) && isNumber(close)) {
    if (close > ema20 && ema20 > ema50) result.mediumTerm = "STRONG_BULLISH";
    else if (close > ema50) result.mediumTerm = "BULLISH";
    else if (close < ema20 && ema20 < ema50) result.mediumTerm = "STRONG_BEARISH";
    else if (close < ema50) result.mediumTerm = "BEARISH";
  }

  if (isNumber(ema50) && isNumber(ema200) && isNumber(close)) {
    if (close > ema50 && ema50 > ema200) result.longTerm = "STRONG_BULLISH";
    else if (close > ema200) result.longTerm = "BULLISH";
    else if (close < ema50 && ema50 < ema200) result.longTerm = "STRONG_BEARISH";
    else if (close < ema200) result.longTerm = "BEARISH";
    else result.longTerm = "NEUTRAL";
  }

  return result;
}

// ---------------------------------------------------------------------

/**
 * supportResistance.js
 *
 * Price-structure based support/resistance engine (spec section 10).
 * Pipeline: detect swing highs/lows -> build candidate levels -> cluster
 * nearby levels (ATR-normalized distance) -> score cluster strength ->
 * pick the 3 nearest supports (below close) and 3 nearest resistances
 * (above close).
 *
 * Only uses candles up to and including the evaluation bar — never future
 * data (spec section 30). Callers must pass an already-sorted, already-
 * truncated candle window ending at the trading date being scanned.
 */


/**
 * Detects swing highs/lows using a symmetric window: a swing high at index i
 * requires candles[i].high to be the strict maximum within [i-wing, i+wing];
 * a swing low requires candles[i].low to be the strict minimum in that range.
 * `wing` defaults to 2 (i.e. 2 bars on each side, a 5-bar fractal).
 *
 * Because the last `wing` bars can't be confirmed yet (no future bars to
 * compare against), the most recent `wing` candles never produce swing
 * points — this is intentional and prevents look-ahead bias from ever being
 * introduced by a caller who accidentally includes "future" bars.
 */
function detectSwingPoints(candles, wing = 2) {
  const swingHighs = [];
  const swingLows = [];

  for (let i = wing; i < candles.length - wing; i++) {
    const windowHighs = candles.slice(i - wing, i + wing + 1).map((c) => c.high);
    const windowLows = candles.slice(i - wing, i + wing + 1).map((c) => c.low);

    const isSwingHigh = candles[i].high === Math.max(...windowHighs) &&
      windowHighs.filter((h) => h === candles[i].high).length === 1;
    const isSwingLow = candles[i].low === Math.min(...windowLows) &&
      windowLows.filter((l) => l === candles[i].low).length === 1;

    if (isSwingHigh) {
      swingHighs.push({ index: i, date: candles[i].date, price: candles[i].high, volume: candles[i].volume });
    }
    if (isSwingLow) {
      swingLows.push({ index: i, date: candles[i].date, price: candles[i].low, volume: candles[i].volume });
    }
  }

  return { swingHighs, swingLows };
}

/**
 * Clusters a list of { index, date, price, volume } points into zones.
 * Two points belong to the same cluster when their price distance is within
 * `atrThreshold` * ATR (falls back to `pctThreshold`% of price when ATR is
 * unavailable, e.g. very short history).
 */
function clusterLevels(points, referenceAtr, referencePrice, atrThreshold = 0.5, pctThreshold = 0.5) {
  if (!points.length) return [];

  const threshold = isNumber(referenceAtr) && referenceAtr > 0
    ? referenceAtr * atrThreshold
    : referencePrice * (pctThreshold / 100);

  // Reference for recency scoring must be the most recent bar INDEX across
  // all points (chronological), not derived from a price-sorted ordering.
  const latestIndex = Math.max(...points.map((p) => p.index));

  const sorted = [...points].sort((a, b) => a.price - b.price);
  const clusters = [];
  let current = [sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const prevPrice = current[current.length - 1].price;
    if (Math.abs(sorted[i].price - prevPrice) <= threshold) {
      current.push(sorted[i]);
    } else {
      clusters.push(current);
      current = [sorted[i]];
    }
  }
  clusters.push(current);

  return clusters.map((cluster) => buildClusterSummary(cluster, latestIndex));
}

/**
 * Scores a cluster's strength using touches, recency, volume near the level,
 * and time separation between touches (more spread-out touches => a more
 * durable, tested level, not just one noisy consolidation).
 */
function buildClusterSummary(clusterPoints, latestIndex) {
  const price = clusterPoints.reduce((sum, p) => sum + p.price, 0) / clusterPoints.length;
  const touches = clusterPoints.length;

  const mostRecentIndex = Math.max(...clusterPoints.map((p) => p.index));
  const recencyScore = latestIndex > 0 ? Math.max(0, 1 - (latestIndex - mostRecentIndex) / latestIndex) : 0;

  const avgVolume = clusterPoints.reduce((sum, p) => sum + (isNumber(p.volume) ? p.volume : 0), 0) / touches;

  const indices = clusterPoints.map((p) => p.index).sort((a, b) => a - b);
  let avgSeparation = 0;
  if (indices.length > 1) {
    let totalSep = 0;
    for (let i = 1; i < indices.length; i++) totalSep += indices[i] - indices[i - 1];
    avgSeparation = totalSep / (indices.length - 1);
  }
  const separationScore = Math.min(1, avgSeparation / 20); // 20+ bars apart = fully "tested over time"

  // Weighted composite, 0-100.
  const touchScore = Math.min(1, touches / 4); // 4+ touches saturates
  const strength =
    touchScore * 40 +
    recencyScore * 25 +
    separationScore * 20 +
    Math.min(1, avgVolume > 0 ? 1 : 0) * 15;

  return {
    price: round(price, 6),
    touches,
    strength: round(clamp(strength, 0, 100), 2),
    avgVolume: round(avgVolume, 2),
    lastTouchIndex: mostRecentIndex,
  };
}

/**
 * Main entry point. `candles` must already be truncated to the lookback
 * window ending at the scan date (spec: ~100-250 sessions, configurable via
 * SUPPORT_RESISTANCE_LOOKBACK). `latestAtr` is the ATR14 value for the last
 * bar (used for clustering distance); pass null to fall back to % clustering.
 *
 * Returns the row shape matching the support_resistance table.
 */
function calculateSupportResistance(candles, latestAtr, wing = 2) {
  if (!Array.isArray(candles) || candles.length < wing * 2 + 3) {
    return {
      support1: null, support2: null, support3: null,
      resistance1: null, resistance2: null, resistance3: null,
      support1Strength: null, support2Strength: null, support3Strength: null,
      resistance1Strength: null, resistance2Strength: null, resistance3Strength: null,
      nearestSupportDistancePct: null, nearestResistanceDistancePct: null,
    };
  }

  const closePrice = candles[candles.length - 1].close;
  const { swingHighs, swingLows } = detectSwingPoints(candles, wing);

  const resistanceClusters = clusterLevels(swingHighs, latestAtr, closePrice)
    .filter((c) => c.price > closePrice)
    .sort((a, b) => a.price - b.price)
    .slice(0, 3);

  const supportClusters = clusterLevels(swingLows, latestAtr, closePrice)
    .filter((c) => c.price < closePrice)
    .sort((a, b) => b.price - a.price)
    .slice(0, 3);

  const [r1, r2, r3] = resistanceClusters;
  const [s1, s2, s3] = supportClusters;

  const nearestResistanceDistancePct = r1 ? ((r1.price - closePrice) / closePrice) * 100 : null;
  const nearestSupportDistancePct = s1 ? ((closePrice - s1.price) / closePrice) * 100 : null;

  return {
    support1: s1 ? s1.price : null,
    support2: s2 ? s2.price : null,
    support3: s3 ? s3.price : null,
    resistance1: r1 ? r1.price : null,
    resistance2: r2 ? r2.price : null,
    resistance3: r3 ? r3.price : null,

    support1Strength: s1 ? s1.strength : null,
    support2Strength: s2 ? s2.strength : null,
    support3Strength: s3 ? s3.strength : null,

    resistance1Strength: r1 ? r1.strength : null,
    resistance2Strength: r2 ? r2.strength : null,
    resistance3Strength: r3 ? r3.strength : null,

    nearestSupportDistancePct: round(nearestSupportDistancePct, 4),
    nearestResistanceDistancePct: round(nearestResistanceDistancePct, 4),
  };
}

// Runs once for the WHOLE batch — one item per active stock arrives here
// from "Load Price History". Must loop $input.all() explicitly (see
// 04-egx-technical-analysis for the same bug pattern, confirmed via live
// E2E testing). itemMatching(i) pairs each row back to its originating stock.

const lookback = Number($env.SUPPORT_RESISTANCE_LOOKBACK) || 150;
const items = $input.all();
const out = [];

for (let itemIdx = 0; itemIdx < items.length; itemIdx++) {
  let original;
  try { original = $('Attach As-Of Date').itemMatching(itemIdx).json; } catch (e) { continue; }
  const symbol = original.symbol;
  const stockId = original.id;
  const backfillAll = original.backfillAll === true;

  const row = items[itemIdx].json;
  const rawCandles = row.candles || [];
  if (!Array.isArray(rawCandles) || rawCandles.length === 0) continue;

  const candles = sortCandlesAscending(rawCandles.map((c) => ({ ...c, symbol })));
  const atrSeries = atr(candles, 14);

  function computeForIndex(i) {
    const windowCandles = candles.slice(Math.max(0, i - lookback + 1), i + 1);
    const latestAtr = atrSeries[i];
    const sr = calculateSupportResistance(windowCandles, latestAtr, 2);
    return { stockId, tradingDate: candles[i].date, ...sr };
  }

  // Require a minimum of 25 bars before attempting any swing detection —
  // fewer than that produces noise, not real structure.
  const minIndex = 24;
  const indices = backfillAll
    ? candles.map((_, i) => i).filter((i) => i >= minIndex)
    : [candles.length - 1];

  for (const i of indices) {
    if (i >= 0 && i < candles.length) out.push({ json: computeForIndex(i) });
  }
}

return out;

const count = $input.first().json.sr_row_count;
return [{ json: {
  workflow: '05-egx-support-resistance',
  finishedAt: new Date().toISOString(),
  supportResistanceRowCount: count,
} }];
